using System.Collections.Generic;
using UnityEngine;

namespace WeddingChaos.View
{
    /// <summary>
    /// Tiny audio manager: one music source, one ambience loop, a pool of one-shot sources.
    /// Clips live in Resources/Audio (generated by Tools/AudioGen). Every effect has a default volume
    /// and a minimum gap so a burst of identical events (20 emotes in one frame) stays pleasant.
    /// </summary>
    public class Sfx : MonoBehaviour
    {
        const int Voices = 10;
        const string PrefSound = "wc_sound", PrefMusic = "wc_music";

        static Sfx inst;
        readonly Dictionary<string, AudioClip> clips = new Dictionary<string, AudioClip>();
        readonly Dictionary<string, float> lastPlayed = new Dictionary<string, float>();
        AudioSource[] pool;
        int next;
        AudioSource music, amb;
        float musicTarget, ambTarget, duck = 1f, duckUntil;

        // name -> (volume, min gap seconds)
        static readonly Dictionary<string, (float vol, float gap)> Defaults = new Dictionary<string, (float, float)>
        {
            { "ui_tap", (0.35f, 0.05f) }, { "select", (0.45f, 0.05f) }, { "lift", (0.3f, 0.08f) }, { "deny", (0.4f, 0.12f) },
            { "seat", (0.5f, 0.06f) }, { "bench", (0.5f, 0.1f) }, { "table_done", (0.6f, 0.3f) }, { "cheer", (0.5f, 0.5f) },
            { "drama_up", (0.5f, 0.15f) }, { "drama_big", (0.6f, 0.6f) }, { "gasp", (0.45f, 0.8f) }, { "drama_down", (0.45f, 0.15f) },
            { "love", (0.45f, 0.2f) }, { "fight", (0.55f, 0.5f) }, { "splat", (0.6f, 0.2f) }, { "gift_tick", (0.5f, 0.05f) },
            { "gift_open", (0.6f, 0.3f) }, { "ribbon_cut", (0.6f, 0.3f) }, { "coin", (0.35f, 0.08f) },
            { "bouncer", (0.4f, 0.3f) }, { "champagne", (0.6f, 0.3f) }, { "emote", (0.18f, 0.12f) },
            { "level_start", (0.45f, 0.5f) }, { "win", (0.65f, 1f) }, { "lose", (0.6f, 1f) },
        };

        public static bool SoundOn
        {
            get => PlayerPrefs.GetInt(PrefSound, 1) == 1;
            set { PlayerPrefs.SetInt(PrefSound, value ? 1 : 0); if (inst) inst.ApplyMix(); }
        }

        public static bool MusicOn
        {
            get => PlayerPrefs.GetInt(PrefMusic, 1) == 1;
            set { PlayerPrefs.SetInt(PrefMusic, value ? 1 : 0); if (inst) inst.ApplyMix(); }
        }

        public static void Ensure()
        {
            if (inst) return;
            var go = new GameObject("Sfx");
            DontDestroyOnLoad(go);
            inst = go.AddComponent<Sfx>();
            inst.Init();
        }

        void Init()
        {
            foreach (var c in Resources.LoadAll<AudioClip>("Audio")) clips[c.name] = c;
            pool = new AudioSource[Voices];
            for (int i = 0; i < Voices; i++)
            {
                var s = gameObject.AddComponent<AudioSource>();
                s.playOnAwake = false; s.spatialBlend = 0; s.priority = 128;
                pool[i] = s;
            }
            music = gameObject.AddComponent<AudioSource>();
            music.loop = true; music.playOnAwake = false; music.priority = 0;
            amb = gameObject.AddComponent<AudioSource>();
            amb.loop = true; amb.playOnAwake = false; amb.priority = 10;
            if (clips.TryGetValue("music_main", out var m)) { music.clip = m; music.volume = 0; music.Play(); }
            if (clips.TryGetValue("amb_crowd", out var a)) { amb.clip = a; amb.volume = 0; amb.Play(); }
            musicTarget = 0.32f; ambTarget = 0.07f;
            ApplyMix();
        }

        void ApplyMix()
        {
            if (!music) return;
            music.mute = !MusicOn;
            amb.mute = !SoundOn;
            foreach (var s in pool) s.mute = !SoundOn;
        }

        void Update()
        {
            if (Time.unscaledTime > duckUntil) duck = Mathf.MoveTowards(duck, 1f, Time.unscaledDeltaTime * 0.8f);
            float k = Time.unscaledDeltaTime * 2f;
            music.volume = Mathf.MoveTowards(music.volume, musicTarget * duck, k * 0.5f);
            amb.volume = Mathf.MoveTowards(amb.volume, ambTarget, k * 0.2f);
        }

        /// <summary>Play a one-shot. vol multiplies the clip's default level; pitch gets a little random spread.</summary>
        public static void Play(string name, float vol = 1f, float pitch = 1f, float spread = 0.04f)
        {
            if (!inst || !SoundOn) return;
            inst.PlayInternal(name, vol, pitch, spread);
        }

        void PlayInternal(string name, float vol, float pitch, float spread)
        {
            if (!clips.TryGetValue(name, out var clip)) return;
            var def = Defaults.TryGetValue(name, out var d) ? d : (0.5f, 0.05f);
            float now = Time.unscaledTime;
            if (lastPlayed.TryGetValue(name, out var last) && now - last < def.Item2) return;
            lastPlayed[name] = now;

            // prefer a free voice, otherwise steal the oldest one
            AudioSource src = null;
            for (int i = 0; i < Voices; i++)
            {
                var s = pool[(next + i) % Voices];
                if (!s.isPlaying) { src = s; next = (next + i + 1) % Voices; break; }
            }
            if (src == null) { src = pool[next]; next = (next + 1) % Voices; }
            src.clip = clip;
            src.volume = def.Item1 * vol;
            src.pitch = pitch * (1f + Random.Range(-spread, spread));
            src.Play();
        }

        /// <summary>Briefly lower the music under a big stinger (win/lose/drama).</summary>
        public static void Duck(float level, float seconds)
        {
            if (!inst) return;
            inst.duck = Mathf.Min(inst.duck, level);
            inst.duckUntil = Time.unscaledTime + seconds;
        }

        /// <summary>The crowd murmur swells as the hall gets more dramatic (0..100).</summary>
        public static void SetDrama(int drama)
        {
            if (!inst) return;
            inst.ambTarget = Mathf.Lerp(0.05f, 0.16f, Mathf.Clamp01(drama / 100f));
        }

        public static void SetMusicLevel(float level)
        {
            if (inst) inst.musicTarget = level;
        }
    }
}
